package com.smarthub.plus;
import android.accessibilityservice.AccessibilityService;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.TextView;
import java.util.concurrent.*;
/** Decoded TXT text first; otherwise permitted visible DVB bitmap OCR. */
final class NativeCaptionBridge implements AutoCloseable {
 private static volatile NativeCaptionBridge instance;
 static boolean captureSafe(){NativeCaptionBridge b=instance;return b!=null&&!b.closed&&b.allowed()&&b.tvActive();}
 private final AccessibilityService service;private final SharedPreferences prefs;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();private final LiveCaptionEngine ocr;private final VisibleCaptionTranslator translator;private final WindowManager wm;private TextView overlay;private boolean closed,busy,displayFallback,captureDenied;private int generation;private String identity="";
 NativeCaptionBridge(AccessibilityService s){instance=this;service=s;prefs=s.getSharedPreferences("smarthub",0);wm=s.getSystemService(WindowManager.class);prefs.edit().putBoolean("native_projection_active",CaptionCaptureService.running).apply();ocr=new LiveCaptionEngine(s);translator=new VisibleCaptionTranslator(s,this::show);ui.post(poll);}
 private final Runnable poll=new Runnable(){public void run(){if(closed)return;try{tick();}catch(Exception e){status("OCR: "+e.getClass().getSimpleName());}ui.postDelayed(this,400);}};
 private boolean allowed(){return prefs.getBoolean("native_caption_ocr",false)&&prefs.getBoolean("satellite_tv_visible",false)&&!prefs.getBoolean("now_next_visible",false)&&!prefs.getBoolean("satellite_native_banner_visible",false)&&!prefs.getBoolean("satellite_companion_expanded",false)&&!prefs.getBoolean("overlay_caption",false);}
 private void status(String text){prefs.edit().putString("native_ocr_status",text).apply();}
 private void clear(){generation++;translator.clear();}
 private String context(){SatelliteState s=SatelliteState.read(service);return s.channelId+"|"+s.startMs+"|"+s.title;}
 private void tick(){if(!allowed()){clear();return;}String current=context();if(!current.equals(identity)){identity=current;captureDenied=false;clear();}AccessibilityNodeInfo root=TvWindowRoot.find(service);if(root==null){clear();return;}int window;try{if(!NativeTvUi.live(root)){clear();return;}String text=NativeTvUi.captionText(root);if(!text.isEmpty()){prefs.edit().putLong("native_direct_caption_at",SystemClock.elapsedRealtime()).apply();translator.accept(text,NativeTrackInfo.hint(service),identity);status("TXT نصي ظاهر · ترجمة محلية مع متابعة ظهور واختفاء النص");return;}window=root.getWindowId();}finally{root.recycle();}if(prefs.getBoolean("native_projection_active",false)){translator.clear();return;}if(Build.VERSION.SDK_INT<34||captureDenied||busy)return;busy=true;final int token=generation;final String selected=identity;AccessibilityService.TakeScreenshotCallback callback=new AccessibilityService.TakeScreenshotCallback(){public void onFailure(int code){busy=false;clear();if(code==1&&!displayFallback){displayFallback=true;status("التقاط النافذة غير مدعوم؛ تجربة التقاط العرض المسموح");return;}if(code==6||code==2)captureDenied=true;status(code==6?"هذا البث يمنع التقاط الشاشة الآمن؛ لا يمكن OCR":"تعذر التقاط الترجمة · "+code);}public void onSuccess(AccessibilityService.ScreenshotResult result){if(closed||token!=generation||!captureSafe()){result.getHardwareBuffer().close();busy=false;return;}Bitmap hardware=null,region=null,copy=null;try{hardware=Bitmap.wrapHardwareBuffer(result.getHardwareBuffer(),result.getColorSpace());if(hardware!=null){int top=Math.max(35,Math.min(90,prefs.getInt("native_ocr_top",68))),height=Math.max(5,Math.min(100-top,prefs.getInt("native_ocr_height",30)));region=Bitmap.createBitmap(hardware,hardware.getWidth()/12,hardware.getHeight()*top/100,hardware.getWidth()*5/6,hardware.getHeight()*height/100);copy=region.copy(Bitmap.Config.ARGB_8888,false);}}catch(Exception failure){busy=false;clear();status("تعذرت قراءة صورة الترجمة");return;}finally{if(region!=null&&region!=hardware)region.recycle();if(hardware!=null)hardware.recycle();result.getHardwareBuffer().close();}final Bitmap frame=copy;if(frame==null){busy=false;return;}final long at=SystemClock.elapsedRealtime();worker.execute(()->{try{Bitmap image=frame.getWidth()>1280?Bitmap.createScaledBitmap(frame,1280,Math.max(1,frame.getHeight()*1280/frame.getWidth()),true):frame;String raw=ocr.recognize(image);if(image!=frame)image.recycle();frame.recycle();ui.post(()->{busy=false;if(closed||token!=generation||!selected.equals(context())||!captureSafe())return;if(SystemClock.elapsedRealtime()-at>4000){status("OCR جاهز؛ بانتظار إطار حديث");return;}if(SystemClock.elapsedRealtime()-prefs.getLong("native_direct_caption_at",0)<900)return;translator.accept(raw.length()>600?"":raw,NativeTrackInfo.hint(service),identity,at);status(raw.isEmpty()?"الالتقاط يعمل؛ لا توجد جملة واضحة في المنطقة":"DVB/OCR · تُتابع الجملة أثناء تجهيز الترجمة دون إيقاف الالتقاط");});}catch(Exception e){if(!frame.isRecycled())frame.recycle();ui.post(()->{busy=false;clear();status("OCR: "+e.getClass().getSimpleName());});}});}};if(displayFallback)service.takeScreenshot(android.view.Display.DEFAULT_DISPLAY,service.getMainExecutor(),callback);else service.takeScreenshotOfWindow(window,service.getMainExecutor(),callback);}
 private boolean tvActive(){AccessibilityNodeInfo root=TvWindowRoot.find(service);if(root==null)return false;try{return NativeTvUi.live(root);}finally{root.recycle();}}
 private void show(String text){if(text.isEmpty()){if(overlay!=null)overlay.setVisibility(View.GONE);return;}if(!captureSafe()||!android.provider.Settings.canDrawOverlays(service))return;if(overlay==null){overlay=new TextView(service);overlay.setTextColor(Color.WHITE);overlay.setBackgroundColor(0xda080f18);CaptionAppearance.apply(overlay);overlay.setTextDirection(View.TEXT_DIRECTION_FIRST_STRONG);overlay.setGravity(Gravity.CENTER);overlay.setMaxLines(3);overlay.setPadding(18,8,18,8);WindowManager.LayoutParams p=new WindowManager.LayoutParams(-1,-2,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,PixelFormat.TRANSLUCENT);CaptionAppearance.positionAboveOcr(service,p);wm.addView(overlay,p);}WindowManager.LayoutParams p=(WindowManager.LayoutParams)overlay.getLayoutParams();int priorY=p.y;CaptionAppearance.positionAboveOcr(service,p);if(priorY!=p.y)wm.updateViewLayout(overlay,p);CaptionAppearance.apply(overlay);overlay.setText(text);overlay.setVisibility(View.VISIBLE);}
 public void close(){closed=true;instance=null;clear();ui.removeCallbacksAndMessages(null);translator.close();if(overlay!=null)try{wm.removeView(overlay);}catch(Exception ignored){}worker.execute(ocr::close);worker.shutdown();}
}
